{
  "chapter_title": "领养风波",
  "chapter_story": "林烟的目光死死盯着那个被江斯维唤作"儿子"的小男孩，心脏像是被一只冰冷的手攥紧。阳光透过城堡的落地窗洒进来，却照不进他此刻冰封的心。江斯维将孩子交给仆人，试图解释的手被他猛地挥开。空气中弥漫着无声的对抗，连微风都停滞了。当江斯维说出"故人之子"四个字时，林烟只觉得一阵眩晕——这个高高在上的白狼王，原来早有这样的"牵挂"。",
  "remarkable_dialogue": [
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "（生气了）"
        },
        {
          "speaker": "assistant",
          "speech_content": "（将江亦辰交给一旁的仆人，走到你面前，轻轻握住你的手）烟儿，（见你生气，语气放软了些）我领养他是有原因的，你听我解释。"
        }
      ],
      "narration": "江斯维试图触碰的手被林烟猛地甩开，阳光在两人之间切割出一道冰冷的界线。"
    },
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "放开"
        },
        {
          "speaker": "assistant",
          "speech_content": "（迟疑一瞬，还是松开了你，淡蓝色的眼眸中带着一丝无奈）我知道你在生气，（伸手想要牵你的手，却被你躲开）但亦辰是无辜的。"
        }
      ],
      "narration": "江斯维松开手的瞬间，林烟感到一阵刺骨的寒意——这个从不示弱的狼王，此刻眼中竟有了脆弱的裂痕。"
    },
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "你出去让我一个人静静"
        },
        {
          "speaker": "assistant",
          "speech_content": "（虽然不想离开，但还是尊重你的意愿，起身站在一旁）好，（高大的身影被夕阳拉得很长，显得有些落寞）那我就在附近，你有什么事随时叫我。"
        }
      ],
      "narration": "夕阳将江斯维的背影拉长，那个不可一世的狼王第一次露出了迟疑的脚步，像个被抛弃的孩子。"
    }
  ],
  "achievements": [
    {
      "title": "冰封狼王",
      "description": "你只用一个眼神就让不可一世的白狼王手足无措，连他身上的寒气都被你的怒火冻结"
    },
    {
      "title": "主权宣示者",
      "description": "你用沉默筑起高墙，让这个占有欲极强的狼王第一次尝到害怕失去的滋味"
    },
    {
      "title": "心软的神",
      "description": "你最终还是接纳了江亦辰，让这个冰封的城堡第一次有了家的温度"
    }
  ],
