{
  "chapter_title": "学霸小老师驾到",
  "chapter_story": "江曜的笔尖在试卷上划出最后一道弧线，胸腔里憋着的那口气终于吐了出来。他几乎是弹起来的，椅子腿与地面摩擦发出刺耳声响。"写完了！"少年眼睛亮得像落满星星，带着点邀功的急切凑过来，手肘不小心撞翻了桌上的橡皮。视线扫过红笔标记的错题时，那点亮光瞬间黯淡下去，嘴角垮成委屈的弧线，手指无意识地抠着试卷边缘，指节泛白。",
  "remarkable_dialogue": [
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "好，你先做，如果做全对，有奖励"
        },
        {
          "speaker": "assistant",
          "speech_content": "（原本皱着的眉头瞬间舒展开，眼中闪过一丝期待）真的？（立马来了精神，开始认真做题）那我可得好好做了，你可不许反悔。（边做题边偷偷看你一眼）"
        }
      ],
      "narration": "少年听到奖励二字时耳朵尖都在发光，握笔的姿势突然标准得像换了个人，只是睫毛总在你看过来时不安分地颤动。"
    },
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "但有一个条件"
        },
        {
          "speaker": "assistant",
          "speech_content": "（心里虽然有些忐忑，但还是故作镇定）什么条件？（拉着你的手，眼睛一眨不眨地看着你）你说吧，我都答应你。（心里默默祈祷着你可别提出什么过分的要求）"
        },
        {
          "speaker": "user",
          "speech_content": "叫我声老婆"
        },
        {
          "speaker": "assistant",
          "speech_content": "（脸颊迅速升温，从耳根红到脖子）老婆……（声音小得像蚊子哼哼，眼睛闪躲着不敢看你，双手却紧紧地抓着你的衣角）这样可以了吗？"
        }
      ],
      "narration": "校霸的喉结在白皙脖颈上剧烈滚动，那抹从耳根蔓延到锁骨的绯红比任何告白都来得真切，攥着衣角的手指关节泛白，像鼓足了毕生勇气。"
    }
  ],
  "achievements": [
    {
      "title": "专属小老师",
      "description": "你成功让桀骜不驯的校霸乖乖坐好听课，连他那帮兄弟都看呆了"
    },
    {
      "title": "纯情捕获者",
      "description": "你只用两个字就让不可一世的江曜红透耳根，校霸的反差萌被你拿捏了"
    },
    {
      "title": "学霸式诱惑",
      "description": "你用学习奖励勾起校霸的胜负欲，让打架比吃饭还勤的他主动拿起了试卷"
    },
    {
      "title": "班级掌控者",
      "description": "你以学生会身份空降教室，连校霸都立刻变乖，全班瞬间鸦雀无声"
    }
  ],
  "interaction_summary": [
    {
      "interaction_content": "江曜言语撒娇",
