{
  "chapter_title": "暴君的专属御医",
  "chapter_story": "星露娜站在萧璟煜面前，感觉自己的心跳快要冲破胸膛。皇帝刚刚放下玉箸，慵懒地倚在榻上，那声低沉的"来为朕揉揉肩膀"像一道不容抗拒的圣旨，在大殿中回荡。她看着他微敞的龙袍领口下若隐若现的锁骨，想起刚才被他紧握到发红的手腕，指尖不由自主地颤抖起来。空气中还残留着御膳的香气，混杂着他身上冷冽的龙涎香，形成一种令人窒息的压迫感。她知道，从踏入这座宫殿的那一刻起，自己就再也无法真正逃离这个男人的掌控了。",
  "remarkable_dialogue": [
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "！你怎么说话不算数呢 ！"
        },
        {
          "speaker": "assistant",
          "speech_content": "笑话！（冷哼一声，双手背在身后，周身散发出强大的气场）朕乃北胤王朝的皇帝，一言九鼎，（面色冰冷地看着你）只是你区区一介平民，也配让朕遵守承诺？"
        }
      ],
      "narration": "萧璟煜冷笑一声，眼中闪过一丝轻蔑，周身散发出的帝王威压让星露娜几乎喘不过气来。她看着眼前这个言而无信的暴君，气得浑身发抖却无能为力。"
    }
  ],
  "achievements": [
    {
      "title": "胆大包天",
      "description": "你竟敢当面指责皇帝说话不算数，这份勇气足以让整个皇宫的人都为你捏一把汗"
    },
    {
      "title": "御医担当",
      "description": "你用精湛医术缓解了暴君的病痛，证明了自己并非浪得虚名，赢得了继续活下去的机会"
    },
    {
      "title": "撒娇高手",
      "description": "你略带撒娇的语气竟让冷酷的暴君心中一颤，成功触动了这座冰山最柔软的角落"
    },
    {
      "title": "逃跑专家",
      "description": "你多次试图逃离暴君身边，虽然每次都被抓包，但这份执着的"自由魂"实在令人敬佩"
    }
  ],
