{
  "chapter_title": "宿管的荒唐指令",
  "chapter_story": "宿管阿姨的话语像一道惊雷炸响在宿舍走廊，许倩情感到血液瞬间冲上头顶。比基尼睡衣？统一着装？荒唐的要求让她浑身僵硬。当宿管将那抹刺眼的粉色塞到她手中时，布料冰凉的触感让她指尖发颤。余光里，许屿川站在原地，平日里冷漠的脸上写满了错愕，耳根却又一次不受控制地泛红。换好衣服走出来的瞬间，她清晰地感受到他目光的重量，那道视线在她身上停留了太久，久到让她几乎要落荒而逃。黑暗中躺在狭窄的单人床上，身旁是许屿川刻意保持的距离，她却能听见他如擂鼓般的心跳声，比宿舍窗外的风声还要清晰。",
  "remarkable_dialogue": [
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": （宿管阿姨那了一套比基尼）宿管：这是女生的统一的睡衣，换上
        },
        {
          "speaker": "assistant",
          "speech_content": （刚闭上的眼睛倏地睁开，不可置信地看向宿管阿姨手中的睡衣）这……（转头看向你，脸上的表情有些一言难尽）确定是给我们宿舍的？
        }
      ],
      "narration": "宿管阿姨将粉色比基尼甩在桌上时，许屿川的手机「啪嗒」一声掉在床单上，纯黑的屏幕映出他错愕的脸。"
    },
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": （宿管：不干净，罚女生两天不能穿衣服）
        },
        {
          "speaker": "assistant",
          "speech_content": （闻言脸色一沉，上前一步挡在你身前）阿姨，（语气难得强硬起来）不干净是我们没打扫好，为什么要罚她？（转头看向你，眼神中带着安抚）你别怕。
        }
      ],
      "narration": "许屿川宽厚的背影突然挡在许倩情身前，肌肉紧绷如拉满的弓，平日里垂落的刘海因愤怒微微颤动。"
    }
  ],
  "achievements": [
    {
      "title": "比基尼室友",
      "description": "你让冰山校霸对着比基尼睡衣目瞪口呆，耳根红得像熟透的樱桃，原来校霸也有纯情时刻。"
    },
    {
      "title": "护花使者",
      "description": "你成功激发校霸保护欲，当宿管刁难时，他像老母鸡护崽般将你挡在身后，男友力MAX！"
