{
  "chapter_title": "孽缘枷锁",
  "chapter_story": "医院门口的风带着消毒水的味道刮过黎簇的脸颊，他能感觉到那些围观者的目光像针一样扎在背上。吴邪的手掌铁钳般扣着他的腰，温热的呼吸喷在颈侧，这个距离近得让他胃里翻江倒海。唾沫啐在对方脸上的瞬间，他听见自己的声音在发抖——不是因为害怕，而是愤怒到了极致。指甲深深掐进车门框的缝隙里，铁锈的味道混着血腥味在舌尖蔓延开来。三个月来的屈辱像潮水般涌进脑海，那些深夜的哭泣、无力的反抗、还有那个混蛋突如其来的吻...现在又要夺走他腹中这个意外的生命。黎簇猛地弓起背，皮鞋后跟狠狠跺在吴邪的脚背上，在对方吃痛的瞬间，他用尽全身力气嘶吼：\"你他妈做梦！\"",
  "remarkable_dialogue": [
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "这个孩子必须打掉"
        },
        {
          "speaker": "assistant",
          "speech_content": "（动作一滞，心底腾起些异样，又被愤怒覆盖）这孩子又不是我一个人的，凭什么你说打掉就打掉？（恶狠狠地瞪你）"
        }
      ],
      "narration": "黎簇的手指深深掐进掌心，指甲缝渗出细密的血珠。阳光在他红肿的眼尾投下细碎的阴影，像只被激怒的幼兽。"
    },
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "乖，听话"
        },
        {
          "speaker": "assistant",
          "speech_content": "（猛地回头瞪你一眼，气得浑身发抖）你他妈让我打掉孩子，还叫我乖？（一口唾沫啐在你脸上）做梦！"
        }
      ],
      "narration": "唾沫星子在吴邪脸上炸开的瞬间，黎簇能听见周围抽气的声音。他的胸膛剧烈起伏着，像只濒死挣扎的困兽。"
    }
  ],
  "achievements": [
    {
      "title": "不屈幼兽",
      "description": "你用最狼狈的姿态对抗强权，唾沫啐脸的瞬间，连绝望都带着锋芒"
    },
    {
      "title": "意外孕夫",
      "description": "你让天不怕地不怕的黎簇怀上孩子，这个"惊喜"足够他记恨一辈子"
    },
    {
      "title": "医院修罗场",
      "description": "你在大庭广众下扛着他闯医院，让桀骜不驯的少年颜面扫地却依旧死不低头"
