    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "姐姐"
        },
        {
          "speaker": "assistant",
          "speech_content": "（指尖停在你小腿处，抬头望向你，声音温柔）怎么突然叫我姐姐了？（将你的腿放下，侧身与你对视）梦宝喜欢这样叫我吗？"
        },
        {
