{
  "chapter_title": "破命之誓",
  "chapter_story": "李文华站在廊下，看着萧雪落穿着单薄的寝衣奔出门来。晨光勾勒出他苍白的面容和微颤的身形，那双总是清冷的盲眼此刻竟流露出毫不掩饰的急切。当他确认站在面前的是自己时，那瞬间绽放的欣喜像初绽的昙花，让李文华的心猛地一缩。这个昨夜还在说着"生死纠缠"的国师，这个曾试图用白绫了断一切的男人，此刻正站在晨光中，像个迷路许久终于找到归宿的孩子。",
  "remarkable_dialogue": [
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "雪儿"
        },
        {
          "speaker": "assistant",
          "speech_content": "（被你连名带姓地称呼，心中有些失落，声音故作冷淡）陛下，直呼臣的名讳，不合规矩。"
        },
        {
          "speaker": "user",
          "speech_content": "过来"
        },
        {
          "speaker": "assistant",
          "speech_content": "（抿了抿唇，还是缓步走过去，站在你面前，声音有些僵硬）陛下，有何吩咐？"
        },
        {
          "speaker": "user",
          "speech_content": "傻瓜，你是我的宝贝，怎么就会不合礼数"
        },
        {
          "speaker": "assistant",
          "speech_content": "（被你突然的话惊得呼吸一滞，脸上泛起红晕，声音微颤）陛下，莫要这般说臣，臣何德何能，担得起您如此厚爱。"
        }
      ],
      "narration": "晨光穿过廊檐，落在萧雪落苍白的脸上，映出他瞬间染红的耳尖。他下意识地攥紧衣袖，却没有后退半步，盲眼微微抬起，仿佛想捕捉女帝此刻的神情。"
    }
  ],
  "achievements": [
    {
      "title": "破誓之君",
      "description": "你用一声"雪儿"打破国师固守的君臣之礼，让冷傲的预言家第一次显露失落神情"
    },
    {
      "title": "宝贝认证师",
      "description": "你将"宝贝"这个称谓冠在国师头上，成功让他惊得呼吸一滞，脸颊绯红"
    },
    {
      "title": "去陛下化者",
      "description": "你剥夺了自己"陛下"的尊号，让前朝国师第一次犹豫着吐出你的私名"清欢""
    },
    {
      "title": "逃犯捕获者",
      "description": "你从黄泉边缘抢回执意寻死的国师，巴掌与拥抱间让他彻底放弃逃离念头"
    },
    {
      "title": "礼数改写者",
      "description": "你用一句"本王就是礼数"噎得国师说不出话，让他耳尖泛红却无力反驳"
    }
  ],
