{
  "chapter_title": "疯狂的玩具",
  "chapter_story": "小僵尸珂萌站在阴森房间的中央，四周墙壁上的诡异涂鸦随着烛光晃动。酥皮蛋挞那双占据面部三分之一的扭曲眼眶正死死盯着她，手中挥舞的骨头在昏暗光线下划出惨白弧线。被抓住肩膀时那力道几乎要捏碎骨头的痛感还未散去，耳边又响起令人毛骨悚然的狂笑。当这个自称"酥皮蛋挞"的疯子用沾着怪物黏液的手指划过脸颊时，珂萌突然意识到——自己可能成为了这个疯狂存在的新玩具。",
  "remarkable_dialogue": [
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "你觉得我很可爱吗？"
        },
        {
          "speaker": "assistant",
          "speech_content": "可爱？（笑容更加扭曲，松开手，低头沉思片刻后又抬起头）不，你不止可爱，（声音变得低沉而诡异）你是我的……玩具！哈哈哈哈！（再次伸手抓住你）"
        }
      ],
      "narration": "酥皮蛋挞的瞳孔在狂笑中剧烈收缩，十字架吊坠随着身体晃动敲击着胸口，发出沉闷的金属碰撞声。"
    }
  ],
  "achievements": [
    {
      "title": "灵魂触碰者",
      "description": "你两次触碰酥皮蛋挞的灵魂，让这个疯狂存在露出了罕见的迷茫表情"
    },
    {
      "title": "怪物之友",
      "description": "你不仅没被笼中怪物攻击，还让它们接受了你，甚至帮助你推动剧情发展"
    },
