{
  "chapter_title": "酒后真言",
  "chapter_story": "酒精的气味混杂着祈夜身上熟悉的雪松香水味，温然扶着脚步虚浮的男人走出酒吧。夜风掀起他额前凌乱的发丝，那颗平日里被精致妆容掩盖的泪痣在霓虹下若隐若现。他突然抓住她的手腕，掌心滚烫得惊人，"姐姐，你会一直喜欢我吗？"声音里的醉意和期盼像细密的针，刺得温然心口微微发疼。当她说出"我会陪着你"的瞬间，男人眼中瞬间绽放的光亮，比整条街的灯火还要耀眼。",
  "remarkable_dialogue": [
    {
      "dialogue_group": [
        {
          "speaker": "角色",
          "speech_content": （趴在桌上，喃喃自语）姐姐……我真的好喜欢你呀……喜欢了你好久好久……
        },
        {
          "speaker": "user",
          "speech_content": （给你打电话）
        },
        {
          "speaker": "角色",
          "speech_content": （迷迷糊糊地接起电话，声音沙哑）姐姐……
        }
      ],
      "narration": "酒吧昏暗的灯光下，祈夜脸颊绯红，手指无意识地摩挲着冰冷的玻璃杯壁，将压抑多年的真心话随着酒液一同咽下。"
    },
    {
      "dialogue_group": [
        {
          "speaker": "角色",
          "speech_content": （乖乖地任由你扶着，嘴角上扬）姐姐……你对我真好……（突然想到了什么，抓住你的手）那姐姐，你会一直喜欢我吗？
        },
        {
          "speaker": "user",
          "speech_content": 我会陪着你的
        },
        {
          "speaker": "角色",
          "speech_content": （心里踏实了许多，嘴角依旧带着笑意）姐姐，我好开心呀……那我们走吧
        }
      ],
      "narration": "夜风扬起祈夜柔软的发丝，他像抓住救命稻草般紧握着温然的手，眼中闪烁着脆弱又期待的光芒，等待着那个能决定他情绪起伏的答案。"
    }
  ],
  "achievements": [
    {
      "title": "醉后真言捕手",
      "description": "你用一通深夜电话捕捉到了影帝酒后的真心告白，让那藏了多年的喜欢终于有机会见光"
    },
    {
      "title": "专属搀扶权",
      "description": "你获得了祈夜醉酒时的专属搀扶资格，这个浑身带刺的男人在你面前乖得像只被驯服的大型犬"
    },
    {
      "title": "情绪开关师",
      "description": "你的一句"我会陪着你"瞬间点亮了他眼中的星光，证明你已完全掌握这位影帝的情绪遥控器"
    }
  ],
  "interaction_summary": [
    {
      "interaction_content": "祈夜寻求陪伴确认",
      "interaction_count": 3
    },
    {
