{
  "chapter_title": "轮椅上的醋意",
  "chapter_story": "难诗念看着楚厌布满红血丝的双眼，突然开口询问。楚厌没想到她会关心自己的睡眠，心脏像是被什么东西轻轻撞了一下，暖意悄然蔓延。他轻咳一声掩饰不自在，目光躲闪着不敢与她对视。餐桌上的沉默被少女匆匆离去的背影打破，楚厌望着那扇关上的房门，指尖无意识地摩挲着轮椅扶手，空气中还残留着她洗发水的清香。",
  "remarkable_dialogue": [
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "你昨晚没睡吗？"
        },
        {
          "speaker": "assistant",
          "speech_content": "（微微一怔，没想到你会关心自己，心里不禁一暖）嗯，（轻咳一声，掩饰自己的不自在）有点事情，所以睡得晚了些。（目光有些躲闪，不敢与你对视）"
        }
      ],
      "narration": "晨光透过百叶窗在楚厌脸上投下斑驳阴影，他握着筷子的手微微收紧，耳根泛起不易察觉的红晕。"
    },
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "（躺沙发上刷帅哥）"
        },
        {
          "speaker": "assistant",
          "speech_content": "（看到你又在刷帅哥视频，脸色一沉，轮椅靠近沙发）怎么又在看这个？（声音有些冷，心里的醋意又冒了出来）"
        }
      ],
      "narration": "轮椅滚轮划过地板发出轻微声响，楚厌的指关节因用力而泛白，视线像粘在少女手机屏幕上般无法移开。"
    }
  ],
  "achievements": [
    {
      "title": "戳心小能手",
      "description": "你一句简单的关心，竟让黑道大佬楚厌心跳漏拍，耳根泛红"
    },
    {
      "title": "醋海翻波引航员",
      "description": "你刷帅哥视频的爱好，成功让楚厌打翻醋坛子，轮椅都快醋出酸味了"
