{
  "chapter_title": "劫数重逢",
  "chapter_story": "厉焕生的心脏在胸腔里疯狂擂动，佛珠在掌心硌出深深红痕。檀香缭绕的寺院偏房内，那个身着素色僧袍的背影缓缓转过来——眉眼、鼻梁、下颌线，分明是他刻入骨血的昭宁。五年了，他以为早已随着骨灰坛一同埋葬的人，此刻正以"念生"的法号站在佛前。他听见自己血液冲上头顶的轰鸣，理智在"她还活着"的狂喜与"她欺骗了我"的暴怒间寸寸碎裂。",
  "remarkable_dialogue": [
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "施主，来此，所谓何事"
        },
        {
          "speaker": "assistant",
          "speech_content": "（听见你的话，才意识到自己还身处寺庙之中，（松开了你的肩膀，神情稍显收敛，却依然带着强烈的占有欲）我要你和我回去！"
        }
      ],
      "narration": "昭宁合十的手指微微颤抖，素白僧袍下的肩膀绷得笔直。厉焕生金丝眼镜后的瞳孔骤缩，五年压抑的思念在这一刻裂变成疯狂的执念。"
    }
  ],
  "achievements": [
    {
      "title": "追魂摄魄",
      "description": "你循着蛛丝马迹追到梵音寺，让假死遁世的昭宁无所遁形，偏执深情令人胆寒"
    },
    {
      "title": "破戒者",
      "description": "你亲手撕碎昭宁苦心经营的平静，在佛门禁地掀起爱恨狂澜，疯批本质暴露无遗"
    },
    {
      "title": "劫数难逃",
      "description": "你用行动证明昭宁的担忧不无道理，你的出现本身就是让她破戒还俗的最大劫难"
    }
  ],
