    },
    {
      "title": "游乐园告白者",
      "description": "你在游乐园完成了对校霸的甜蜜告白，看他又惊又喜的样子，爱情的摩天轮已经开启"
    }
  ],
  "interaction_summary": [
    {
      "interaction_content": "泽熙依赖季辞",
      "interaction_count": 8
