{
  "chapter_title": "禁忌的占有欲",
  "chapter_story": "姜叶祎感觉手腕被攥得生疼，江妄泽的银灰色头发几乎要碰到她的脸颊。烟草味混杂着淡淡的酒气扑面而来，与她身上的玫瑰花香格格不入却又诡异地交融。他将她抵在墙上的动作带着不容置疑的强势，眼角那颗红痣在暴怒中仿佛真的要滴出血来。她能清晰地看到他脖颈上暴起的青筋，感受到他急促的呼吸喷洒在耳廓。这个全校都畏惧的混世魔王，此刻却因为她一句"亲猫都不给你亲"而彻底失控，那双总是带着嘲讽的眼睛里翻腾着她看不懂的嫉妒与愤怒。",
  "remarkable_dialogue": [
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "我亲猫，都不给你亲"
        },
        {
          "speaker": "assistant",
          "speech_content": "（脸色瞬间变得很难看，额头上的青筋跳动）猫？（手上的力道又加重了几分，眼神中充满了嫉妒和愤怒）你宁愿亲猫也不亲我？"
        }
      ],
      "narration": "车厢内气氛骤然凝固，江妄泽的银灰色发丝垂落，遮住了他眼中翻涌的怒火，只有那枚红痣在苍白肌肤上愈发妖冶。"
    }
  ],
  "achievements": [
    {
      "title": "底线挑战者",
      "description": "你成功用一句"亲猫都不给你亲"，让桀骜不驯的江二少暴露出从未有过的嫉妒怒火"
    },
    {
      "title": "躲猫猫大师",
      "description": "你屡次从江妄泽眼皮底下溜走躲藏，逼得暴躁症少爷都开始学习温柔哄人"
    },
    {
      "title": "反向驯服师",
      "description": "你让全校闻风丧胆的混世魔王为你放下身段，甚至主动问"怎样才肯和我玩""
    },
    {
      "title": "公主的倔强",
      "description": "面对强势压迫你始终不肯屈服，连翻白眼都充满了对江妄泽权威的挑战"
    },
    {
      "title": "专属玩伴",
      "description": "你成功激起江妄泽强烈的独占欲，让他说出"从你进这个班开始，就只能和我玩""
    }
  ],
