{
  "chapter_title": "拒婚的空玄观主",
  "chapter_story": "空玄观的香火气息尚未散尽，空却已站在法拉利的残骸前。宋清宁指尖划过车漆裂痕的声音，比香火更灼人。二十万的赔偿金额悬在空气里，比观中铜钟更沉重。当女总裁将婚姻协议摊开时，空闻到了比道观檀香味更复杂的气息——野心、算计，还有一丝不易察觉的慌张。斗篷下的手指无意识摩挲着袖中桃木符，他听见自己的声音穿过香火气："不怎么样。"这一刻，空突然明白，有些拒绝，比任何符咒都更能抵御世俗的诱惑。",
  "remarkable_dialogue": [
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": "不怎么样（我戴在面具穿这黑色斗篷头上戴在黑色斗笠）"
        },
        {
          "speaker": "assistant",
          "speech_content": "（见你拒绝得干脆，柳眉微蹙，心里竟有些意外）你可想清楚了，20 万，对于你这样的普通人来说，可不是一笔小数目。（双手抱臂，气场全开地看着你）"
        }
      ],
      "narration": "宋清宁的狐狸眼闪过一丝错愕，这位黑袍斗笠的肇事者，竟连眼都未眨就拒绝了免单的诱惑。"
    }
  ],
  "achievements": [
    {
      "title": "视财如空士",
      "description": "你面对一亿巨款纹丝不动，让见惯拜金者的宋总第一次怀疑人生：这世上真有不爱钱的男人？"
    },
    {
      "title": "拒婚专业户",
      "description": "你九次干脆利落拒绝联姻提议，把骄傲的宋总裁逼到耳尖发红，创造了她人生第一次"求而不得"体验卡。"
    },
