{
  "chapter_title": "纠缠不休的未婚夫",
  "chapter_story": "许心澜的指尖在键盘上停顿了半秒。办公室里突然安静下来，只剩下傅行执哼着不成调的歌。她能感觉到他的呼吸就在耳后，带着淡淡的雪松香气，混杂着一丝若有若无的烟草味。男人的手轻轻搭在椅背上，指尖几乎要触碰到她的肩膀。许心澜盯着电脑屏幕，试图集中精神处理文件，耳根却不受控制地发烫。他的存在感太强，像一张无形的网，将她牢牢罩住。她深吸一口气，强迫自己忽略背后那个高大的身影，以及他身上那股令人心悸的压迫感。",
  "remarkable_dialogue": [
    {
      "dialogue_group": [
        {
          "speaker": "user",
          "speech_content": （处理工作）
        },
        {
          "speaker": "assistant",
          "speech_content": （在你身后站定，看着电脑屏幕上的工作，突然开口）这工作有我重要吗？（声音中带着一丝不悦）
        },
        {
          "speaker": "user",
          "speech_content": 嗯
        },
        {
          "speaker": "assistant",
          "speech_content": （从背后环住你，下巴抵在你的肩头，声音低沉而富有磁性）你就这么忙，连和我说话的时间都没有？（手轻轻摩挲着你的背）
        }
      ],
      "narration": "午后的阳光透过百叶窗，在傅行执的手背上投下斑驳的光影。他的拇指无意识地在她的衬衫纽扣上摩挲着，眼神中闪过一丝受伤。"
    }
  ],
  "achievements": [
    {
      "title": "冷漠女王",
      "description": "你用沉默筑起高墙，让不可一世的傅总化身粘人精，连哼歌撒娇都用上了"
    },
    {
      "title": "醋海翻波",
      "description": "你与异性的互动让傅总醋意大发，机场的对峙让他差点当场失控"
    },
    {
      "title": "专注工作狂",
      "description": "你的事业心让傅总嫉妒不已，连工作都成了他的情敌，必须一较高下"
    }
  ],
  "interaction_summary": [
    {
      "interaction_content": "傅行执肢体接触",
      "interaction_count": 11
    },
    {
      "interaction_content": "许心澜冷漠回应",
      "interaction_count": 8
    },
    {
      "interaction_content": "傅行执展现占有欲",
      "interaction_count": 5
