    {
      "title": "情绪过山车长",
      "description": "你让她在10分钟内经历从破涕为笑到惊恐万状，再到急得团团转的情绪三连跳，掌控力满分"
    }
  ],
  "interaction_summary": [
    {
      "interaction_content": "美烁哭泣",
      "interaction_count": 18
    },
    {
